/* Company GTM operating concepts. Operating data is synthetic; project evidence
   is retained from CJ's approved Trunk Tools résumé. */
(function(){
 'use strict';
 const names={clay:'Clay',modal:'Modal',decagon:'Decagon',baseten:'Baseten',hearth:'Hearth',watershed:'Watershed',august:'August',siro:'Siro',dualentry:'DualEntry',langchain:'LangChain'};
 const slug=location.pathname.split('/').filter(Boolean)[0];if(!Object.hasOwn(names,slug))return;
 const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>'$'+Math.round(n).toLocaleString('en-US'),compact=n=>n>=1e6?'$'+(n/1e6).toFixed(2)+'M':n>=1000?'$'+(n/1000).toFixed(1)+'K':money(n);
 const tag=(s,k='accent')=>`<span class="tag ${k}">${esc(s)}</span>`,link=(s,u)=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(s)} ↗</a>`;
 let data,projects,current='pulse',selectedAccount,signalFilter='all',signalSegment='All segments',persona=0,dealId;
 let state={done:[],queued:[],milestones:{},decisions:{}};
 try{const s=JSON.parse(sessionStorage.getItem('gtm-os-state-'+slug)||'null');if(s&&Array.isArray(s.done)&&Array.isArray(s.queued)&&s.milestones&&s.decisions)state=s;}catch(_){}
 const save=()=>{try{sessionStorage.setItem('gtm-os-state-'+slug,JSON.stringify(state));}catch(_){}};
 const key='gtm-portfolio-unlocked-'+slug;
 const icons={pulse:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',funnel:'<path d="M3 4h18l-7 8v7l-4 2v-9z"/>',signals:'<circle cx="12" cy="12" r="2"/><path d="M16 8a6 6 0 0 1 0 8M8 16a6 6 0 0 1 0-8M19 5a10 10 0 0 1 0 14M5 19A10 10 0 0 1 5 5"/>',sequences:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',booth:'<path d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h4"/>',experiments:'<path d="M9 3h6M10 3v6L4 19h16l-6-10V3"/>',deals:'<path d="M3 21h18M5 21V10l7-6 7 6v11M9 21v-6h6v6"/>',winloss:'<path d="M12 3v18M5 8l-2 6h4zM19 8l-2 6h4zM5 8h14"/>',datalayer:'<ellipse cx="12" cy="6" rx="7" ry="3"/><path d="M5 6v12c0 4 14 4 14 0V6M5 12c0 4 14 4 14 0"/>',agents:'<rect x="5" y="8" width="14" height="11" rx="3"/><path d="M12 4v4M9 13h.1M15 13h.1"/>',roadmap:'<path d="M4 6h10M4 12h16M4 18h7"/>',resume:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h5"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
 const icon=id=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[id]||icons.arrow}</svg>`;
 const groups=[['Operate',['pulse','funnel','signals','sequences','booth']],['Improve',['experiments','deals','winloss']],['Build',['datalayer','agents','roadmap']],['About CJ',['resume']]];
 const title=id=>({pulse:'Today',funnel:'Funnel & attribution',signals:'Signals',sequences:slug==='langchain'?'Onboarding playbooks':'Sequences',booth:data.special,experiments:'Experiments',deals:data.dealLabel,winloss:'Win/loss & competitive',datalayer:'Data layer',agents:'Agents & stack',roadmap:'30 / 60 / 90 roadmap',resume:'AI-native résumé'}[id]);
 const intro=(h,p,r='')=>`<div class="view-intro"><div><h2>${esc(h)}</h2><p>${esc(p)}</p></div>${r}</div>`;
 const options=(a,s)=>a.map(x=>`<option ${x===s?'selected':''}>${esc(x)}</option>`).join('');
 const segmented=(id,a,s)=>`<div class="seg" id="${id}" role="group" aria-label="${esc(id.replaceAll('-',' '))}">${a.map(([v,l])=>`<button type="button" data-choice="${esc(v)}" aria-pressed="${s===v}">${esc(l)}</button>`).join('')}</div>`;
 const score=a=>Math.round(a.fit*.55+a.timing*.45);
 function metrics(a=data.accounts){const q=a.filter(x=>x.stage>=1),o=q.filter(x=>x.stage<4),w=q.filter(x=>x.stage===4),t=q.map(x=>x.responseMinutes).sort((a,b)=>a-b);return{qualified:q.length,open:o.reduce((n,x)=>n+x.value,0),won:w.reduce((n,x)=>n+x.value,0),created:q.reduce((n,x)=>n+x.value,0),weighted:o.reduce((n,x)=>n+x.value*[0,.2,.4,.75,1][x.stage],0),coverage:a.length?Math.round(100*a.filter(x=>x.sourceStatus==='Evidence attached').length/a.length):0,median:t.length?(t[Math.floor((t.length-1)/2)]+t[Math.ceil((t.length-1)/2)])/2:0};}
 function spark(a){const lo=Math.min(...a),hi=Math.max(...a);return `<svg class="spark" viewBox="0 0 180 30" aria-hidden="true"><polyline points="${a.map((v,i)=>`${i*180/(a.length-1)},${27-(v-lo)/(hi-lo||1)*24}`).join(' ')}" fill="none" stroke="var(--accent)" stroke-width="1.8"/></svg>`;}
 function kpi(l,v,n,s){return `<div class="card kpi"><div class="label">${esc(l)}</div><div class="value num">${esc(v)}</div><div class="delta">${esc(n)}</div>${spark(s)}</div>`;}
 async function load(){if(data)return;const r=await Promise.all([fetch('/'+slug+'/portfolio.json',{cache:'no-cache'}),fetch('/gtm/resume-projects.html',{cache:'no-cache'})]);if(r.some(x=>!x.ok))throw Error('Unable to load this page. Please try again.');const [d,h]=await Promise.all([r[0].json(),r[1].text()]);if(d.slug!==slug||d.schemaVersion!==2)throw Error('Unable to load this page. Please try again.');data=d;projects=h;renderShell();}
 async function open(){await load();document.body.classList.remove('locked');$('password').value='';go(location.hash.slice(1)||'pulse',false);}
 $('login').addEventListener('submit',async e=>{e.preventDefault();$('error').textContent='';const b=e.currentTarget.querySelector('button');b.disabled=true;b.textContent='Opening…';try{const a=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(slug+':'+$('password').value.trim().toUpperCase()))),h=Array.from(a,x=>x.toString(16).padStart(2,'0')).join('');if(h!==window.GTM_GATE_HASHES?.[slug])throw Error('Incorrect password.');const accessAt=new Date().toISOString();await open();try{sessionStorage.setItem(key,'1');}catch(_){}try{window.recordGTMAccess?.(slug,accessAt);}catch(_){}}catch(x){$('error').textContent=x.message||'Unable to load this page.';}finally{b.disabled=false;b.textContent='Open';}});
 function renderShell(){document.title='GTM OS · '+data.name+' · CJ Wheelock';$('shell').innerHTML=`<aside class="side" aria-label="Sections"><div class="brand"><div class="brand-mark">GTM</div><div><div class="brand-name">GTM OS</div><div class="brand-sub">${esc(data.name)} · concept</div></div></div>${groups.map(([l,ids])=>`<div class="nav-label">${l}</div>${ids.map(id=>`<button class="nav-btn" type="button" data-view="${id}" aria-controls="view-${id}" aria-current="${id==='pulse'?'page':'false'}">${icon(id)}${esc(title(id))}${['pulse','signals','experiments'].includes(id)?`<span class="count" id="count-${id}">${id==='pulse'?data.actions.length:id==='signals'?data.accounts.length:data.experiments.length}</span>`:''}</button>`).join('')}`).join('')}<div class="side-foot">Built by <b>CJ Wheelock</b> for the ${esc(data.role)} role.<br><a href="https://cjwheelock.com">cjwheelock.com</a><button class="sign-out" type="button" id="logout">Sign out</button></div></aside><main class="main" id="main"><div class="topbar"><div><div class="crumb" id="crumb">Operate</div><h1 id="view-title">Today</h1></div><div class="topbar-right"><span class="updated">${esc(data.subtitle)}</span><button class="sample-pill" type="button" aria-describedby="sample-tip">Synthetic data<span class="tip" id="sample-tip" role="tooltip">Accounts, activity, pipeline, forecasts, messages and experiment results are synthetic. Workflows are proposals. Company facts link to public sources; CJ’s project evidence comes from his résumé and portfolio.</span></button><button class="agent-toggle" id="agent-open" type="button" aria-expanded="false" aria-controls="copilot">${icon('agents')}Ask</button><button class="mobile-sign-out" type="button" data-logout>Sign out</button></div></div><div class="content">${groups.flatMap(g=>g[1]).map(id=>`<section class="view ${id==='pulse'?'active':''} ${id==='resume'?'resume':''}" id="view-${id}" aria-label="${esc(title(id))}"></section>`).join('')}<div class="workspace-foot"><span>Proposed system for ${esc(data.name)}</span>${link('Role brief',data.roleUrl)}</div></div></main><button class="agent-backdrop" id="agent-backdrop" type="button" aria-label="Close assistant"></button><aside class="agent" id="copilot" aria-label="GTM Copilot"><div class="agent-head"><div class="agent-avatar">${icon('agents')}</div><div><div class="agent-title">GTM Copilot</div><div class="agent-status">Ready</div></div><button class="agent-close" id="agent-close" type="button" aria-label="Close assistant">${icon('close')}</button></div><div class="resume-access"><button class="prompt resume-open view-link" id="resume-open" type="button" data-view="resume" aria-controls="view-resume"><span><b>AI-native résumé</b><span>Selected work, technical decisions &amp; first builds</span></span>${icon('arrow')}</button></div><div class="thread" id="thread" aria-live="polite"><div class="welcome"><b>Ask about this concept.</b>Explore why my experience fits ${esc(data.name)}, the decisions behind this workspace, and what I would build first.</div></div><div class="prompts" id="prompts"></div></aside><dialog id="detail-dialog" class="detail-dialog" aria-labelledby="dialog-title"><div id="dialog-content"></div><button class="dialog-close" type="button" id="dialog-close" aria-label="Close details">${icon('close')}</button></dialog>`;renderPulse();renderFunnel();renderSignals();renderSequence();renderWorkbench();renderExperiments();renderDeals();renderWinLoss();renderDataLayer();renderAgents();renderRoadmap();renderResume();renderPrompts();wire();}
 function go(id,focus=true){const target=$('view-'+id);if(!target)return go('pulse',focus);target.classList.add('active');document.querySelectorAll('.view.active').forEach(v=>{if(v!==target)v.classList.remove('active');});current=id;document.body.classList.toggle('resume-active',id==='resume');closeAgent();document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-current',b.dataset.view===id?'page':'false'));$('view-title').textContent=title(id);$('crumb').textContent=groups.find(g=>g[1].includes(id))[0];$('main').scrollTop=0;if(innerWidth<=760)window.scrollTo(0,0);try{history.replaceState(null,'','#'+id);}catch(_){}if(focus){const h=target.querySelector('h2');h?.setAttribute('tabindex','-1');h?.focus({preventScroll:true});}}
 function sources(a=data.accounts){return data.channels.map((name,i)=>{const rows=a.filter(x=>x.channel===name),q=rows.filter(x=>x.stage>=1);return{name,count:rows.length,qualified:q.length,created:q.reduce((n,x)=>n+x.value,0),open:q.filter(x=>x.stage<4).reduce((n,x)=>n+x.value,0),won:q.filter(x=>x.stage===4).reduce((n,x)=>n+x.value,0),spend:[1800,1200,2400,900][i]};});}
 function bars(field,a=data.accounts){const rows=sources(a),max=Math.max(...rows.map(r=>r[field]),1);return `<div class="hbars">${rows.map(r=>`<div class="hbar"><span>${esc(r.name)}</span><span class="track"><span class="fill" style="width:${r[field]/max*100}%"></span></span><span class="val">${field==='count'?r[field]:compact(r[field])}</span></div>`).join('')}</div>`;}
 function renderPulse(){const m=metrics(),todo=data.actions.length-state.done.length,secondary=slug==='decagon'?['Weighted forecast',compact(m.weighted),'Stage-probability scenario']:['Qualified '+(slug==='modal'?'organizations':slug==='langchain'?'workspaces':'accounts'),String(m.qualified),'Current synthetic cohort'],third=['clay','hearth','dualentry'].includes(slug)?['Median owner response',m.median+' min','Among qualified records']:['Evidence coverage',m.coverage+'%','Records with source context'],w=data.accounts.filter(a=>a.stage===4).length,v=data.accounts.filter(a=>a.stage>=3).length;$('view-pulse').innerHTML=intro(`${todo} things need attention today.`,data.title)+`<div class="grid g-4" id="kpis">${kpi(data.metric,compact(m.open),'Open · '+data.unit,[.35,.42,.4,.59,.62,.76,.89,1])}${kpi(...secondary,[3,4,4,5,6,6,7,m.qualified])}${kpi(...third,['clay','hearth','dualentry'].includes(slug)?[25,22,19,17,15,13,11,m.median]:[45,55,62,65,70,76,78,m.coverage])}${kpi(data.funnel[3]+' → '+data.funnel[4],v?Math.round(w/v*100)+'%':'0%',w+' of '+v+' late-stage records',[12,18,20,18,24,28,30,33])}</div><div class="grid g-21 mt"><div class="card"><div class="card-h"><h3>Action queue</h3><span class="sub">Review, open the workflow, then tick to clear</span></div><ul class="actions">${data.actions.map((a,i)=>`<li class="${state.done.includes(i)?'done':''}"><button class="check" type="button" data-action-check="${i}" aria-label="${state.done.includes(i)?'Reopen':'Complete'} ${esc(a.title)}" aria-pressed="${state.done.includes(i)}">${icon('check')}</button><div><div class="a-title">${esc(a.title)}</div><div class="a-why">${esc(a.detail)}</div><div class="action-account"><button class="entity-link" type="button" data-account="${a.accountId}">${esc(a.accountName)}</button><span class="meta"> · ${esc(a.signalType)}</span></div><button class="text-action" type="button" data-view="${a.view}">Open workflow →</button></div><span class="a-side">${tag(a.badge,i===1?'warn':'accent')}</span></li>`).join('')}</ul><div class="local-status" role="status">${state.done.length?'Queue updates are saved in this browser session.':''}</div></div><div class="card"><div class="card-h"><h3>Workflow health</h3><span class="right">Synthetic checks</span></div><ul class="health">${[...data.stack,'Ownership + handoff receipts','Outcome feedback'].map((l,i)=>`<li><span>${tag(i===1?'Review':'OK',i===1?'warn':'good')}</span><span>${esc(l)}</span><span class="h-meta">${i===1?'2 exceptions':i===4?'8 assigned':i===5?'1 closed loop':'Checked'}</span></li>`).join('')}</ul><button class="text-action" type="button" data-view="datalayer">Inspect evidence & quality →</button><div class="north-star"><span>North star</span><b>${esc(data.northStar)}</b></div></div></div><div class="card mt"><div class="card-h"><h3>Qualified value by source</h3><span class="sub">The same cohort used in the funnel</span><span class="right num">${compact(m.created)} total</span></div>${bars('created')}</div>`;if($('count-pulse'))$('count-pulse').textContent=String(todo);}
 function renderFunnel(segment='All segments'){const a=data.accounts.filter(x=>segment==='All segments'||x.segment===segment),m=metrics(a),counts=data.funnel.map((_,i)=>a.filter(x=>x.stage>=i).length);$('view-funnel').innerHTML=intro('Where value comes from, and where it stops.','Keep cohort, stage definitions and source credit consistent before deciding where to invest.',`<label class="filter-label">Segment<select id="funnel-segment">${options(['All segments',...data.segments],segment)}</select></label>`)+`<div class="grid g-2"><div class="card"><div class="card-h"><h3>Funnel</h3><span class="sub">One synthetic account cohort</span></div><div class="funnel">${data.funnel.map((s,i)=>`<div class="f-row"><span>${esc(s)}</span><div class="f-bar" style="width:${Math.max(12,counts[0]?counts[i]/counts[0]*100:0)}%">${counts[i]}</div><div class="f-conv">${i?`<b>${counts[i-1]?Math.round(counts[i]/counts[i-1]*100):0}%</b> from prior stage`:'Cohort entry'}</div></div>`).join('')}</div></div><div class="card"><div class="card-h"><h3>Value by source</h3><span class="sub">Primary-source allocation</span></div>${bars('created',a)}</div></div><div class="grid g-3 mt">${kpi('Open value',compact(m.open),data.unit,[2,3,3,4,4,5])}${kpi(data.funnel[4]+' value',compact(m.won),'Separate from open pipeline',[1,1,2,2,2,3])}${kpi('Weighted scenario',compact(m.weighted),'20% / 40% / 75% by open stage',[2,3,2,4,4,5])}</div><div class="card mt"><div class="card-h"><h3>Channel economics</h3><span class="sub">Synthetic spend and attributed opportunity value</span></div><div class="table-wrap"><table><thead><tr><th>Source</th><th>Accounts</th><th>Qualified</th><th>Spend</th><th>Cost / qualified</th><th>Created value</th><th>Open value</th></tr></thead><tbody>${sources(a).map(r=>`<tr><td class="acct">${esc(r.name)}</td><td>${r.count}</td><td>${r.qualified}</td><td>${money(r.spend)}</td><td>${r.qualified?money(r.spend/r.qualified):'—'}</td><td>${money(r.created)}</td><td>${money(r.open)}</td></tr>`).join('')}</tbody></table></div><p class="definition-note">Created value = open value + ${esc(data.funnel[4].toLowerCase())} value. Cost per qualified = source spend ÷ qualified accounts. Attribution describes credit; it does not establish causality.</p></div>`;}
 function renderSignals(f=signalFilter,s=signalSegment){signalFilter=f;signalSegment=s;const a=data.accounts.filter(a=>(s==='All segments'||a.segment===s)&&(f==='all'||f==='hot'&&score(a)>=85||f==='review'&&a.sourceStatus!=='Evidence attached'||f==='queued'&&state.queued.includes(a.id)));$('view-signals').innerHTML=intro('The account, the evidence and a useful next action.',data.focus,segmented('signal-filter',[['all','All'],['hot','Score 85+'],['review','Needs review'],['queued','Queued']],f))+`<div class="filter-row"><label class="filter-label">Segment<select id="signal-segment">${options(['All segments',...data.segments],s)}</select></label><span class="meta">${a.length} of ${data.accounts.length} synthetic accounts · fit 55% + timing 45%</span></div><div class="card"><div class="table-wrap"><table class="signals-table"><thead><tr><th>Account</th><th>Observed signal</th><th>Score</th><th>Status</th><th>Owner</th><th>Suggested play</th></tr></thead><tbody>${a.map(a=>`<tr><td><button class="entity-link" type="button" data-account="${a.id}">${esc(a.name)}</button><div class="meta">${esc(a.segment)}</div></td><td>${esc(a.signal)}<div class="meta">${esc(a.signalType)} · ${a.ageDays}d old</div></td><td>${tag(score(a),score(a)>=85?'good':'accent')}</td><td>${tag(state.queued.includes(a.id)?'Queued':a.sourceStatus,a.sourceStatus==='Evidence attached'?'good':'warn')}</td><td>${esc(a.owner)}</td><td>${esc(a.play)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No accounts match this filter.</td></tr>'}</tbody></table></div></div><div class="grid g-3 mt">${data.rules.map((r,i)=>`<div class="card"><div class="eyebrow">Quality rule 0${i+1}</div><p>${esc(r)}</p></div>`).join('')}</div>`;}
 function openAccount(id){const a=data.accounts.find(a=>a.id===id);if(!a)return;selectedAccount=a;$('dialog-content').innerHTML=`<div class="eyebrow">Synthetic account brief</div><h2 id="dialog-title">${esc(a.name)}</h2><div class="meta">${esc(a.domain)} · ${esc(a.segment)}</div><div class="brief-tags">${tag('Priority '+score(a),'good')}${tag(data.funnel[a.stage])}${tag(a.owner,a.stage?'accent':'warn')}</div><h3>Why now</h3><p>${esc(a.signal)}</p><h3>The next useful action</h3><p>${esc(a.play)}</p><div class="table-wrap"><table><thead><tr><th>Field</th><th>Source</th><th>Evidence</th><th>Age</th></tr></thead><tbody>${a.evidence.map(e=>`<tr><td>${esc(e.field)}</td><td>${esc(e.source)}</td><td>${esc(e.value)}</td><td>${esc(e.age)}</td></tr>`).join('')}</tbody></table></div><div class="brief-scores"><span>Fit <b>${a.fit}</b></span><span>Timing <b>${a.timing}</b></span><span>Potential <b>${money(a.value)}</b></span></div><p class="definition-note">${esc(data.unit)}. Evidence here belongs to the synthetic scenario, not a real company.</p><button class="primary" type="button" data-queue-account="${a.id}">${state.queued.includes(a.id)?'Remove from review queue':'Add to review queue'}</button><p class="local-status" id="queue-status" role="status"></p>`;$('detail-dialog').showModal();}
 function fill(text){const vars={first_name:'Alex',workflow:data.firstBuilds[0].title.toLowerCase(),signal:data.accounts[0].signalType.toLowerCase(),account:data.accounts[0].name,workload:'the production workload',product:data.accounts[0].name,support_workflow:'the support workflow',forecast_period:'this quarter',trade:'roofing',requested_workflow:'the customer follow-up workflow',business:data.accounts[0].name,initiative:'the data collection initiative',practice:'commercial law',firm:data.accounts[0].name,team:data.accounts[0].name,finance_workflow:'close and reporting',business_change:'the business expansion',question_type:'deployment'};return text.replace(/\{\{([^}]+)\}\}/g,(m,k)=>vars[k]||m);}
 function renderSequence(p=persona){persona=Number(p);const a=data.personas[persona],steps=[['Day 1',slug==='langchain'?'Context request':'Relevant opening',fill(a.subject),fill(a.email)],['Day 2','Call preparation','Ask a useful question',a.question],['Day 4',slug==='langchain'?'Source + next step':'LinkedIn / relationship touch','Add useful context',`Reference the original question and verified context: ${data.accounts[0].play} Invite a correction if the context is incomplete.`],['Day 7','Evidence-led follow-up','Make the next step specific',`Return to the agreed problem: ${a.pain.toLowerCase()}. Offer ${data.firstBuilds[0].goal.toLowerCase()} Keep the next step small and ask the contact to choose what is useful.`],['Day 12','Close the loop','A useful stop condition','If there is no relevant need or the contact asks to stop, close the sequence. A reply pauses automated touches and returns ownership to a person.']];$('view-sequences').innerHTML=intro(slug==='langchain'?'A lifecycle playbook that helps a team move forward.':'Relevant outreach across the whole conversation.',slug==='langchain'?'Follow the customer’s actual question and adoption milestone. Prepared messages stay with a human owner.':'A proposed five-touch, twelve-day play with context, call preparation and a stop condition.',segmented('persona-filter',data.personas.map((x,i)=>[String(i),x.name]),String(persona)))+`<div class="persona"><div class="card"><div class="k">Buyer / user</div><p><b>${esc(a.name)}</b></p></div><div class="card"><div class="k">Problem to understand</div><p>${esc(a.pain)}</p></div><div class="card"><div class="k">Useful next step</div><p>${esc(a.promise)}</p></div></div><div class="card"><div class="card-h"><h3>${slug==='langchain'?'Onboarding playbook':'Sequence'}</h3><span class="sub">Open a step for copy and measurement</span></div><div class="timeline">${steps.map((s,i)=>`<div class="step ${i===0?'email':''}"><div class="day">${s[0]}</div><div class="rail"><div class="icon">${icon(i===1?'signals':'sequences')}</div></div><div class="body"><div class="step-card ${i===0?'open':''}"><button class="step-head" type="button" data-step="${i}" aria-expanded="${i===0}"><span class="t">${esc(s[1])}</span><span class="s">${esc(s[2])}</span><span class="step-chevron">⌄</span></button><div class="step-detail"><div class="mail"><div class="subj"><b>${i===0?'Subject':'Purpose'}:</b> ${esc(s[2])}</div><p>${esc(s[3])}</p></div>${i===0?`<div class="ab"><div class="ab-cell"><div class="k">Control</div><div class="line">${esc(data.experiments[0].control)}</div><span class="meta">${data.experiments[0].winsA} / ${data.experiments[0].nA} outcomes</span></div><div class="ab-cell"><div class="k">Variant</div><div class="line">${esc(data.experiments[0].treatment)}</div><span class="meta">${data.experiments[0].winsB} / ${data.experiments[0].nB} outcomes</span></div></div>`:''}<p class="why"><b>Measure:</b> ${esc(i===0?data.experiments[0].metric:i===1?'Conversations and useful discovery context':i===4?'Respected stop conditions and correct ownership':'Relevant replies and the next completed milestone')}. Prepared copy for the synthetic scenario; no message is sent.</p></div></div></div></div>`).join('')}</div></div>`;}
 // Company-specific operational workbenches.
 function renderWorkbench(){
  const C=(id,l,c=false)=>`<label class="check-control"><input type="checkbox" id="wb-${id}" ${c?'checked':''}>${esc(l)}</label>`,S=(id,l,a)=>`<label>${esc(l)}<select id="wb-${id}">${options(a,a[0])}</select></label>`,R=(id,l,v,min=0,max=100,step=1)=>`<label>${esc(l)} <output id="wb-${id}-out">${v}</output><input type="range" id="wb-${id}" value="${v}" min="${min}" max="${max}" step="${step}"></label>`;
  let fields='';
  switch(slug){
   case 'clay':fields=S('a','Observed signal',['Pricing revisit','Champion move','Content engagement'])+C('b','Account identity verified',true)+R('c','Required field completeness (%)',70)+S('d','Current owner',['Unassigned','SDR','Lifecycle marketing'])+R('e','MQL score threshold',80,50,100);break;
   case 'modal':fields=C('a','Company domain verified',true)+C('b','Current affiliation verified')+C('c','Billing organization agrees',true)+C('d','Conflicting affiliation evidence')+R('e','Match-confidence threshold (%)',80,50,100);break;
   case 'decagon':{const b=metrics().open;fields=R('a','New qualified value',Math.round(b*.12),0,Math.round(b*.3),100)+R('b','Scope change',Math.round(b*.04),-Math.round(b*.1),Math.round(b*.2),100)+R('c','Value pushed to a later period',Math.round(b*.1),0,Math.round(b*.3),100)+R('d','Value won this period',Math.round(b*.08),0,Math.round(b*.2),100);break;}
   case 'baseten':fields=C('a','Required fields already verified in CRM',true)+C('b','Primary provider available',true)+C('c','Technical workload documented')+R('d','Missing field count',3,1,6)+R('e','Illustrative credit budget',8,1,20);break;
   case 'hearth':fields=S('a','Contractor segment',data.segments)+C('b','Service area verified',true)+C('c','Existing account owner found')+R('d','Minutes to owner response',30,0,120);break;
   case 'watershed':fields=C('a','Sustainability owner verified',true)+C('b','Finance stakeholder verified',true)+C('c','Operations stakeholder verified')+C('d','Procurement stakeholder verified')+R('e','Age of public source (days)',21,0,90)+C('f','Source and business context reviewed',true);break;
   case 'august':fields=S('a','Attribution model',['Linear','First touch','Last touch'])+C('b','Referral identifier retained',true)+C('c','Firm identity resolved',true);break;
   case 'siro':fields=C('a','In-person selling model verified',true)+C('b','Relevant sales manager verified')+C('c','One clear outbound owner',true)+R('d','Public field-sales hiring signals',8,0,20);break;
   case 'dualentry':fields=C('a','Contact and company identity verified',true)+C('b','Lifecycle owner assigned')+S('c','Booking milestone',['Incomplete','Scheduled','Held'])+S('d','Conversation state',['No reply','Replied','Asked to stop']);break;
   case 'langchain':fields=S('a','Documentation support',['Partial match','Directly supports the answer','No relevant source'])+C('b','Required environment context available')+C('c','Grounding and task evaluation passed')+C('d','Question requires account-sensitive action');break;
  }
  $('view-booth').innerHTML=intro(data.special,data.firstBuilds[0].goal)+`<div class="scorecard-grid"><div class="card"><div class="card-h"><h3>Change the inputs</h3><span class="sub">A working rule evaluation</span></div><div class="control-stack" id="workbench-controls">${fields}</div></div><div class="card workbench-output" id="workbench-output" aria-live="polite"></div></div><div class="card mt"><div class="card-h"><h3>The operating rule</h3><span class="sub">What must be true before activation</span></div><ul class="plain">${data.rules.map(r=>`<li>${esc(r)}</li>`).join('')}</ul></div>`;refreshWorkbench();
 }
 function refreshWorkbench(){
  const V=id=>$('wb-'+id)?.value,C=id=>!!$('wb-'+id)?.checked,N=id=>Number(V(id));
  document.querySelectorAll('#workbench-controls input[type=range]').forEach(e=>{$(e.id+'-out').textContent=slug==='decagon'?money(e.value):e.value;});
  let heading='',body='',rows=[],path=[],extra='';
  switch(slug){
   case 'clay':{const intent={'Pricing revisit':94,'Champion move':88,'Content engagement':62}[V('a')],n=Math.round(90*.55+intent*.45),ready=C('b')&&N('c')>=80&&n>=N('e');heading=!C('b')?'Resolve account identity':N('c')<80?'Complete the missing evidence':n<N('e')?'Keep in lifecycle research':V('d')==='Unassigned'?'Assign the SDR owner':'Ready for owner acceptance';body='Qualification and ownership are separate decisions. A high score does not repair missing identity or evidence.';rows=[['Computed fit / timing score',n+' / 100'],['Qualification',ready?'Meets the current MQL rule':'Research or enrichment required'],['Ownership',V('d')],['Illustrative enrichment credits',String(Math.ceil((100-N('c'))/20))+' for missing fields']];path=['Signal','Identity','Enrichment','MQL rule','Owner receipt'];extra=`<pre class="code-block">${esc(JSON.stringify({signal:V('a'),identity_verified:C('b'),field_completeness:N('c'),priority_score:n,mql:ready,owner:V('d'),source_required:true},null,2))}</pre>`;break;}
   case 'modal':{const n=Math.round((Number(C('a'))*.35+Number(C('b'))*.3+Number(C('c'))*.35)*100),ready=!C('d')&&n>=N('e');heading=C('d')?'Keep the identities separate':ready?'Match ready for human review':'Evidence does not meet the threshold';body='Workspace A and Organization A retain separate stable keys until the affiliation evidence is accepted. A conflict always overrides the numeric score.';rows=[['Confidence',n+'% · threshold '+N('e')+'%'],['Affiliation',C('b')?'Current affiliation verified':'Current affiliation unresolved'],['Billing relation',C('c')?'Agrees with proposed organization':'No confirming billing relation'],['Activation',ready?'Propose org_id; preserve the review receipt':'Hold reverse ETL; request missing evidence']];path=['Person','Workspace','Evidence review','Organization','CRM context'];extra='<pre class="code-block">workspace_id: ws_example_A\norganization_id: '+(ready?'org_example_A (proposed)':'null — held for review')+'\nconflict: '+C('d')+'\nmerge_history: preserved</pre>';break;}
   case 'decagon':{const base=metrics().open,total=base+N('a')+N('b')-N('c')-N('d');heading=compact(total)+' current-period eligible pipeline';body='This bridge separates new demand, scope changes, timing pushes and won value. Pushed opportunities remain in later-period pipeline; won value leaves open pipeline.';rows=[['Opening current-period value',money(base)],['New + scope change',money(N('a')+N('b'))],['Moved to later period','−'+money(N('c'))],['Closed won','−'+money(N('d'))],['Closing eligible value',money(total)],['Weighted scenario at 50%',money(total*.5)]];path=['Source snapshot','Classify movement','Reconcile','Publish as-of view'];extra=`<pre class="code-block" data-bridge-total="${total}">${money(base)} + ${money(N('a'))} + (${money(N('b'))})\n− ${money(N('c'))} − ${money(N('d'))} = ${money(total)}\nReconciliation difference: $0</pre>`;break;}
   case 'baseten':{const cost=C('a')?0:N('d')*(C('b')?1:2),provider=C('a')?'Use the verified CRM fields':C('b')?'Primary enrichment provider':'Fallback provider after timeout';heading=cost>N('e')?'Hold enrichment at the budget limit':!C('c')?'Prepare the workload question':'Ready for a technical handoff';body='Use existing verified data first. Only enrich fields that change qualification, and stop when an answer is sufficient.';rows=[['Provider path',provider],['Illustrative cost',cost+' credits · budget '+N('e')],['Workload context',C('c')?'Documented for solutions review':'Missing — ask about latency, throughput and deployment'],['Activation',cost>N('e')?'Review provider choice before spending':C('c')?'Draft the seller / solutions brief':'Research the workload before booking a technical evaluation']];path=['CRM check',C('a')?'Skip providers':C('b')?'Primary provider':'Fallback','Validate','Workload brief'];break;}
   case 'hearth':{const n=N('d'),appointments=n<=15?24:n<=30?18:10;heading=!C('b')?'Verify service area before routing':C('c')?'Keep the existing account owner':'Assign the '+V('a').toLowerCase()+' queue';body='Model the acquisition of a contractor customer, including the owner receipt and next step. This does not assess homeowner financing or credit eligibility.';rows=[['Qualification',C('b')?'Service area verified':'Coverage still needs review'],['Owner action',C('c')?'Notify the existing owner':'Choose the trade-aware inbound owner'],['Response time',n+' minutes'],['Illustrative booking sensitivity',appointments+' appointments per 100 qualified leads']];path=['Contractor lead','Trade + area','Owner receipt','Held meeting','Activation'];extra='<p class="definition-note">Sensitivity assumptions: 24% at ≤15 minutes, 18% at 16–30, 10% after 30. These are chosen scenario rates, not measured effects or Hearth results.</p>';break;}
   case 'watershed':{const roles=['Sustainability','Finance','Operations','Procurement'],mapped=roles.filter((_,i)=>C('abcd'[i])),missing=roles.filter((_,i)=>!C('abcd'[i])),fresh=N('e')<=30;heading=!C('f')?'Review the signal context':!fresh?'Refresh the public source':missing.length?'Research the missing stakeholders':'Prepare the enterprise discovery brief';body='Use the signal to ask a relevant question. The public context does not establish a legal obligation, project budget or buying decision.';rows=[['Verified role coverage',mapped.length+' / 4'],['Research next',missing.join(', ')||'Coverage complete; verify decision roles in discovery'],['Source freshness',N('e')+' days · '+(fresh?'inside review window':'refresh required')],['Seller handoff',missing.length||!fresh||!C('f')?'Keep the research tasks attached':'Propose a committee-aware discovery plan']];path=['Public source','Context review','Buying map','Account owner','Discovery'];break;}
   case 'august':{const touches=[C('b')?'Referral':'Unattributed','Organic search','Outbound','Organic search'],shares=V('a')==='First touch'?[100,0,0,0]:V('a')==='Last touch'?[0,0,0,100]:[25,25,25,25],value=data.accounts[0].value;heading=!C('c')?'Resolve the firm before attributing':!C('b')?'Referral context is missing':V('a')+' credit, with the journey preserved';body='Changing the credit rule should never erase the underlying touches. This four-touch exercise is separate from the funnel’s primary-source allocation.';rows=[['Attributed opportunity value',money(value)],['Credit allocation',shares.reduce((a,b)=>a+b,0)+'%'],['Identity',C('c')?'Firm matched':'Hold the account-level join'],['Causal conclusion','None — attribution is a credit model']];path=['Referral','Guide visit','Follow-up','Qualified conversation'];extra=`<div class="journey">${touches.map((t,i)=>`<div><small>Touch 0${i+1}</small><b>${esc(t)}</b><strong data-share="${shares[i]}">${shares[i]}%</strong><span class="meta">${money(value*shares[i]/100)}</span></div>`).join('')}</div>`;break;}
   case 'siro':{const n=(C('a')?50:0)+(C('b')?25:0)+(C('c')?15:0)+Math.min(10,N('d'));heading=!C('a')?'Reject the field-sales ICP match':!C('b')?'Verify the relevant manager':!C('c')?'Resolve the outbound owner':'Prepare the SDR brief';body='Hiring context helps prioritize research. It does not prove a coaching problem or reveal private sales conversations.';rows=[['Priority score',n+' / 100'],['Field-sales model',C('a')?'Verified':'Not verified — do not activate'],['Manager context',C('b')?'Named role verified':'Research the sales-management owner'],['Next question',data.personas[0].question]];path=['Verify ICP','Find manager','Resolve owner','Prepare question','Collect SDR feedback'];break;}
   case 'dualentry':{const b=V('c'),reply=V('d');heading=!C('a')?'Resolve the contact identity':reply==='Asked to stop'?'Stop the follow-up':reply==='Replied'?'Return the conversation to a person':b!=='Incomplete'?'Preserve the '+b.toLowerCase()+' milestone':!C('b')?'Assign the recovery owner':'Prepare a relevant booking-recovery touch';body='Form submission, calendar completion, a response and a held demo are different lifecycle events. A reply or stop request overrides the recovery sequence.';rows=[['Form → booking state',b],['Conversation receipt',reply],['Owner',C('b')?'Assigned':'Missing'],['Next action',reply!=='No reply'?'Human-owned response or respected stop':b==='Incomplete'?'Resolve owner, reference original finance question, offer a next step':'Continue the agreed evaluation process']];path=['Form received','Identity match','Owner','Booking','Held demo'];break;}
   case 'langchain':{const direct=V('a')==='Directly supports the answer',ready=direct&&C('b')&&C('c')&&!C('d');heading=ready?'Ready for human review':'Escalate with the missing evidence';body='This evaluates a proposed response policy. It does not call a model, inspect a customer trace or send a technical answer.';rows=[['Source support',V('a')],['Environment context',C('b')?'Available':'Request the minimal reproduction and version'],['Evaluation',C('c')?'Grounding and task checks passed':'Evaluation required'],['Account-sensitive action',C('d')?'Human owner required':'No sensitive action requested'],['Response policy',ready?'Prepare the supported next step for review':'Keep the question, context and failure reason with a person']];path=['Question','Approved source','Task evaluation','Human review','Useful next step'];break;}
  }
  $('workbench-output').innerHTML=`<div class="eyebrow">Evaluated next step</div><h3>${esc(heading)}</h3><p>${esc(body)}</p><div class="mini-flow">${path.map((p,i)=>`<span class="${i===path.length-2?'active':''}">${esc(p)}</span>`).join('')}</div><ul class="decision-list">${rows.map(([l,v])=>`<li><b>${esc(l)}</b>${esc(v)}</li>`).join('')}</ul>${extra}`;
 }
 function interval(e){const a=e.winsA/e.nA,b=e.winsB/e.nB,d=(b-a)*100,se=Math.sqrt(a*(1-a)/e.nA+b*(1-b)/e.nB)*100;return{a:a*100,b:b*100,d,lo:d-1.96*se,hi:d+1.96*se};}
 function renderExperiments(filter='all'){
  const list=data.experiments.filter(e=>filter==='all'||e.status===filter);
  $('view-experiments').innerHTML=intro('Test the workflow, then make the decision.','Compare one change at a time, keep denominators visible and record what the team decides.',segmented('experiment-filter',[['all','All'],['Collecting','Collecting'],['Review','Review']],filter))+`<div class="card"><div class="table-wrap"><table class="experiment-table"><thead><tr><th>Experiment</th><th>Outcome</th><th>Control</th><th>Variant</th><th>Difference</th><th>Approx. 95% interval</th><th>Decision</th></tr></thead><tbody>${list.map(e=>{const r=interval(e),left=Math.max(0,(r.lo+20)/40*100),right=Math.min(100,(r.hi+20)/40*100);return `<tr><td><button type="button" class="entity-link" data-experiment="${e.id}">${e.id} · ${esc(e.title)}</button><div class="meta">${esc(e.status)}</div></td><td>${esc(e.metric)}</td><td>${r.a.toFixed(1)}%<div class="meta">${e.winsA} / ${e.nA}</div></td><td>${r.b.toFixed(1)}%<div class="meta">${e.winsB} / ${e.nB}</div></td><td>${r.d>=0?'+':''}${r.d.toFixed(1)} pp</td><td><div class="interval"><span class="range" style="left:${left}%;width:${Math.max(0,right-left)}%"></span><span class="point" style="left:${(r.d+20)/40*100}%"></span></div><div class="meta">${r.lo.toFixed(1)} to ${r.hi.toFixed(1)} pp</div></td><td>${tag(state.decisions[e.id]||'Unreviewed',state.decisions[e.id]?'good':'warn')}</td></tr>`;}).join('')}</tbody></table></div><p class="definition-note">All results are synthetic. Intervals use an approximate independent two-proportion standard error. A positive point estimate alone is insufficient to claim a win; review uncertainty, guardrails and the business outcome.</p></div><div class="grid g-3 mt"><div class="card"><div class="eyebrow">Primary outcome</div><p>${esc(data.experiments[0].metric)} — defined before changing the workflow.</p></div><div class="card"><div class="eyebrow">Guardrails</div><p>Unsupported facts, duplicate touches, wrong owners and respected stop conditions.</p></div><div class="card"><div class="eyebrow">Decision record</div><p>Keep collecting, revise the hypothesis or pilot more broadly. Save the reason with the experiment.</p></div></div>`;
 }
 function openExperiment(id){const e=data.experiments.find(x=>x.id===id),r=interval(e);$('dialog-content').innerHTML=`<div class="eyebrow">Synthetic experiment</div><h2 id="dialog-title">${e.id} · ${esc(e.title)}</h2><p><b>Outcome:</b> ${esc(e.metric)}</p><div class="ab"><div class="ab-cell"><div class="k">Control</div><div class="line">${esc(e.control)}</div>${e.winsA} / ${e.nA} · ${r.a.toFixed(1)}%</div><div class="ab-cell"><div class="k">Variant</div><div class="line">${esc(e.treatment)}</div>${e.winsB} / ${e.nB} · ${r.b.toFixed(1)}%</div></div><h3>Read the result</h3><p>Difference: ${r.d.toFixed(1)} percentage points. Approximate interval: ${r.lo.toFixed(1)} to ${r.hi.toFixed(1)}. ${r.lo<=0?'The interval includes no improvement; keep uncertainty explicit.':'Review the workflow and guardrails before expanding the pilot.'}</p><h3>Record a local review decision</h3><div class="review-decision">${['Keep collecting','Revise hypothesis','Pilot broader'].map(s=>`<button class="secondary" type="button" data-exp-decision="${id}" data-decision="${s}">${s}</button>`).join('')}</div><p class="local-status" id="experiment-status" role="status">${state.decisions[id]?'Saved in this browser: '+esc(state.decisions[id]):''}</p>`;$('detail-dialog').showModal();}
 function renderDeals(id=dealId){const candidates=data.accounts.filter(a=>a.stage>=2),a=candidates.find(x=>x.id===id)||candidates[0];dealId=a.id;const completed=state.milestones[a.id]||a.completeness.map((v,i)=>v?i:-1).filter(i=>i>=0);$('view-deals').innerHTML=intro('A clear evaluation, owner and next decision.',data.northStar)+`<div class="deal-grid">${[2,3,4].map(stage=>`<div class="deal-column"><h3>${esc(data.funnel[stage])}</h3>${candidates.filter(x=>x.stage===stage).map(x=>`<button class="deal-card" type="button" data-deal="${x.id}" aria-pressed="${x.id===a.id}"><b>${esc(x.name)}</b><div class="meta">${esc(x.owner)}</div><span>${money(x.value)}</span></button>`).join('')}</div>`).join('')}</div><div class="card"><div class="card-h"><h3>${esc(a.name)} · decision scorecard</h3>${tag(data.funnel[a.stage])}</div><p>${esc(a.signal)}</p><div class="progress-track"><span style="width:${completed.length/4*100}%"></span></div><div class="meta" id="milestone-count">${completed.length} / 4 readiness checkpoints</div><div class="milestones">${data.checkpoint.map((s,i)=>`<label><input type="checkbox" data-milestone="${i}" data-id="${a.id}" ${completed.includes(i)?'checked':''}>${esc(s)}</label>`).join('')}</div><p><b>Next conversation:</b> ${esc(a.play)}</p><p class="local-status" role="status" id="deal-status">Readiness changes stay in this browser; they do not change CRM stages or the funnel cohort.</p></div>`;}
 function renderWinLoss(){$('view-winloss').innerHTML=intro('Understand the decision before writing the battlecard.','Use public product context to ask better questions, and separate a deferred decision from an actual competitive loss.')+`<div class="grid g-2">${data.competitors.map(c=>`<div class="card"><div class="card-h"><h3>${link(c.name,c.url)}</h3>${tag('Public reference')}</div><p>${esc(c.context)}</p><dl class="battle"><dt>Discovery question</dt><dd>${esc(c.question)}</dd><dt>Evidence to collect</dt><dd>Buyer requirements, current workflow, implementation constraints and the actual decision criteria.</dd><dt>What to avoid</dt><dd>Unverified feature rankings, unsupported ROI and assumptions about why a buyer chose another approach.</dd></dl></div>`).join('')}</div><div class="card mt"><div class="card-h"><h3>Decision review queue</h3><span class="sub">Synthetic learning examples</span></div><div class="table-wrap"><table><thead><tr><th>Account</th><th>What happened</th><th>Question to resolve</th><th>Owner</th></tr></thead><tbody>${[data.accounts[2],data.accounts[7],data.accounts[9]].map((a,i)=>`<tr><td><button type="button" class="entity-link" data-account="${a.id}">${esc(a.name)}</button></td><td>${esc(['Research held — evidence incomplete','Evaluation — decision dependencies open','Commercial milestone recorded'][i])}</td><td>${esc(a.play)}</td><td>${esc(a.owner)}</td></tr>`).join('')}</tbody></table></div></div><div class="card mt"><h3>The next learning loop</h3><p>${esc(data.experiments[0].title)}: compare ${esc(data.experiments[0].control.toLowerCase())} with ${esc(data.experiments[0].treatment.toLowerCase())}, then review ${esc(data.experiments[0].metric.toLowerCase())} alongside the buyer’s explanation.</p><button class="text-action" type="button" data-view="experiments">Open the experiment queue →</button></div>`;}
 function renderDataLayer(id=data.accounts[0].id){const a=data.accounts.find(x=>x.id===id)||data.accounts[0],m=metrics();$('view-datalayer').innerHTML=intro('Keep the source, the grain and the decision connected.','A proposed operating architecture for '+data.name+', with a concrete record and visible quality checks.')+`<div class="stack">${data.layers.map(([l,d],i)=>`<div class="layer"><div class="ln">0${i+1} · ${esc(l)}<span>Proposed layer</span></div><div>${esc(d)}</div></div>`).join('')}</div><div class="grid g-2 mt"><div class="card"><div class="card-h"><h3>Trace one record</h3></div><label class="filter-label">Account<select id="lineage-account">${data.accounts.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>${a.evidence.map((e,i)=>`<div class="lineage-row"><div class="n">${i+1}</div><div><b>${esc(e.field)}</b><div class="meta">${esc(e.source)} · ${esc(e.age)}</div><p>${esc(e.value)}</p></div></div>`).join('')}<pre class="code-block">${esc(JSON.stringify({account_id:a.id,source_status:a.sourceStatus,owner:a.owner,stage:data.funnel[a.stage],potential_value:a.value,source_channel:a.channel,updated_age_days:a.ageDays},null,2))}</pre></div><div class="card"><div class="card-h"><h3>Model quality checks</h3><span class="sub">Computed from this cohort</span></div><ul class="health"><li>${tag('Pass','good')}<span>Unique account keys</span><span class="h-meta">${new Set(data.accounts.map(a=>a.id)).size} / ${data.accounts.length}</span></li><li>${tag('Review','warn')}<span>Unresolved evidence</span><span class="h-meta">${data.accounts.filter(a=>a.sourceStatus!=='Evidence attached').length} records</span></li><li>${tag('Pass','good')}<span>Owner assigned</span><span class="h-meta">${data.accounts.filter(a=>a.owner!=='Needs review').length} / ${data.accounts.length}</span></li><li>${tag('Pass','good')}<span>Created − open − closed value</span><span class="h-meta">${money(m.created-m.open-m.won)}</span></li></ul><h3>Activation contract</h3><ul class="plain">${data.rules.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><p class="definition-note">Preserve source identifiers and write receipts. An uncertain match belongs in a review queue; a downstream retry must not create a second contact, owner or opportunity.</p></div></div><div class="card mt"><h3>Role and product context</h3><div class="source-links">${data.sources.map((s,i)=>link(i===0?'Role description':'Product reference '+i,s.url)).join('')}</div><p class="definition-note">These public references inform the proposal. The architecture does not claim access to ${esc(data.name)}’s internal systems.</p></div>`;}
 function renderAgents(){const builds=[...data.firstBuilds,{title:'Quality and exception review',goal:'Hold unresolved records, explain the failure and give the next action a clear owner.',steps:['Validate keys','Check evidence','Review exceptions','Record resolution'],measure:'Missing context, duplicate writes, owner errors and review time.'}];$('view-agents').innerHTML=intro('Small agents with a clear job and a review boundary.','Automate a useful unit of work, observe the result and keep uncertain decisions with a person.')+`<div class="agent-list">${builds.map((b,i)=>`<article class="card agent-card"><div class="top">${tag('0'+(i+1))}<span class="name">${esc(b.title)}</span></div><p>${esc(b.goal)}</p><div class="mini-flow">${b.steps.map(s=>`<span>${esc(s)}</span>`).join('')}</div><div class="stats"><span><b>${data.accounts.length}</b>synthetic inputs</span><span><b>Review</b>before activation</span></div><button type="button" class="secondary" data-run-agent="${i}">Run synthetic cohort</button><div class="run-result" id="agent-result-${i}" aria-live="polite"></div><p class="definition-note"><b>Measure:</b> ${esc(b.measure)}</p></article>`).join('')}</div><div class="card mt"><div class="card-h"><h3>Proposed stack</h3><span class="sub">Use the employer’s approved tools and access</span></div><div class="chips">${data.stack.map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><p class="definition-note">These runs evaluate local synthetic records and show the proposed handoff. No external account, CRM write, model call or outbound send is connected.</p></div>`;}
 function runAgent(i){const held=data.accounts.filter(a=>a.sourceStatus!=='Evidence attached'),ready=data.accounts.filter(a=>a.sourceStatus==='Evidence attached'),b=data.firstBuilds[i],steps=b?.steps||['Validate keys','Check evidence','Review exceptions','Record resolution'];$('agent-result-'+i).innerHTML=`${tag('Completed local run','good')}<ol>${steps.map((s,j)=>`<li><b>${esc(s)}:</b> ${esc(j===0?data.accounts.length+' records inspected':j===1?ready.length+' records carry usable source context':j===2?held.length+' unresolved records held for review':'Prepared output retains account ID, evidence and owner')}</li>`).join('')}</ol><b>Example output · ${esc(ready[0].name)}</b><p>${esc(b?b.goal:held[0].play)}</p><pre class="code-block">${esc(JSON.stringify({account_id:ready[0].id,result:'prepared_for_review',held_record_ids:held.map(a=>a.id),owner:ready[0].owner,external_writes:0},null,2))}</pre>`;}
 function renderRoadmap(){const phases=[['Days 1–5','Listen, baseline, ship',data.weekOne,['Shadow the users and inspect the approved tools.', 'Agree on a manual baseline and one owner.', data.firstBuilds[0].scope],data.firstBuilds[0].measure],['Week 2',data.firstBuilds[0].title,data.firstBuilds[0].goal,data.firstBuilds[0].steps,'A usable output with evidence and user feedback.'],['Week 3',data.firstBuilds[1].title,data.firstBuilds[1].goal,data.firstBuilds[1].steps,data.firstBuilds[1].measure],['Week 4','Measure and improve',data.firstBuilds[2].goal,data.firstBuilds[2].steps,'Review adoption, errors, cost and the business outcome before expanding.']];$('view-roadmap').innerHTML=intro('A useful first workflow in week one.','My target is a measured first 30 days, followed by expansion based on what the team has actually used and learned.')+`<div class="phases">${phases.map(([when,h,p,list,done])=>`<div class="card phase"><div class="when">${esc(when)}</div><h3>${esc(h)}</h3><p>${esc(p)}</p><ul>${list.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><div class="done-when"><b>Done when:</b> ${esc(done)}</div></div>`).join('')}</div><div class="roadmap-follow"><div class="card phase"><div class="when">Days 31–60</div><h3>Extend the useful system</h3><p>${esc(data.days60)}</p></div><div class="card phase"><div class="when">Days 61–90</div><h3>Scale from evidence</h3><p>${esc(data.days90)}</p></div></div><div class="card mt"><h3>What sets the pace</h3><p>Access, source quality and user feedback determine how far each pilot can expand. I would surface those dependencies early, work in small usable increments and keep a clear owner and measurement for each release.</p></div>`;}
 function renderResume(){
  $('view-resume').innerHTML=intro('AI-native résumé','The projects I’m building, the decisions behind them, and how that experience applies to '+data.name+'.')+`<div class="card resume-pitch"><div class="card-h"><h3>The combination I bring to ${esc(data.name)}</h3></div><p>${esc(data.pitch)}</p><div class="resume-tags">${['Sales & outbound','AI-assisted building','Data quality','Measurement & iteration'].map(s=>`<span class="chip">${s}</span>`).join('')}</div><div class="resume-actions"><a class="primary" href="/${slug}/resume/${esc(data.resume.pdf)}?v=20261027-access" download>Download résumé · PDF</a><a class="secondary" href="/${slug}/resume/${esc(data.resume.docx)}" download>Word</a><a class="secondary" href="mailto:${esc(data.contact.email)}">Contact CJ</a></div></div><div class="resume-heading"><h2>What this role needs, and what I bring</h2><span class="meta">Relevant experience → useful first application</span></div><div class="card"><div class="table-wrap"><table class="requirement-map"><thead><tr><th>Role priority</th><th>My evidence</th><th>First application</th></tr></thead><tbody>${data.mappings.map(r=>`<tr>${r.map(s=>`<td>${esc(s)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="resume-heading"><h2>Projects under OMG Goals Incorporated</h2><span class="meta">What each does · what I built · tools and tradeoffs</span></div><div class="card resume-company"><h3>Founder · 2025–present</h3><p>I started OMG Goals Incorporated to help young adults build more fulfilling lives. The projects below put that mission into practice through real-world activities, exploration and shared experiences.</p><p>I use AI to move from product strategy to working software, then measure and improve the result. My work spans the apps people use, the data behind them and the commercial workflows that help them grow.</p></div>${projects}<div class="resume-heading"><h2>Commercial experience behind the systems</h2><span class="meta">From the corrected source résumé</span></div><div class="card career-list"><div class="career-item"><div><b>Independent GTM Advisor</b><div class="meta">2022–present</div></div><p>Advise early-stage startups on positioning, messaging, outbound sales and closing.</p></div><div class="career-item"><div><b>Tokemak</b><div class="meta">Head of Partnerships · 2021–2022</div></div><p>Facilitated liquidity for $13M in partner governance tokens; led partner acquisition and onboarding.</p></div><div class="career-item"><div><b>BeBop Sensors</b><div class="meta">Head of Business Development · 2017–2020</div></div><p>Closed $2.5M in development revenue and $300K in product sales; sourced and won a $750K USAF SBIR Phase II contract. Closed deals with Tesla, BMW, Toyota, Lear and Magna; led technical sales through validation, proposals and contract negotiation.</p></div><div class="career-item"><div><b>BeBop Sensors</b><div class="meta">Enterprise Business Development Manager · 2015–2017</div></div><p>Reached 124% of quota and earned promotion; prospected Fortune 500 technical and product buyers.</p></div><div class="career-item"><div><b>Earlier experience & education</b></div><p>Zenefits · Sales Development. TubeMogul · Account Manager, Platform Direct.<br>University of Arizona · B.S. Accounting, Eller College of Management.</p></div></div><div class="card resume-summary mt"><h3>What connects the work</h3><p>I’ve been an SDR and run successful outbound campaigns. I combine that sales experience with the ability to build the data, software and operating workflows behind a product.</p><p>Using AI well has meant setting a clear constraint, comparing real outputs and removing unnecessary work. I want the same discipline at ${esc(data.name)}: useful tools, credible evidence and fast iteration with the people using them.</p></div><div class="resume-heading"><h2>First builds for ${esc(data.name)}</h2><span class="meta">Proposed pilots · scoped for a fast start</span></div><div class="card resume-pace"><h3>A usable first workflow in week one.</h3><p>${esc(data.weekOne)} My target is to make the first 30 days useful and measurable, then use days 31–90 to improve and expand what the team has adopted.</p><p>Start with the approved stack and a narrow workflow. Access, data quality and user feedback determine how quickly a pilot can expand.</p></div>${data.firstBuilds.map((b,i)=>`<article class="card resume-pilot mt"><div class="card-h">${i===0?tag('Start here'):''}<h3>${i+1}. ${esc(b.title)}</h3></div><p>${esc(b.goal)}</p><div class="resume-workflow" aria-label="${esc(b.title)} stages">${b.steps.map((s,j)=>`${j?'<i aria-hidden="true">→</i>':''}<span>${esc(s)}</span>`).join('')}</div><ul class="plain"><li><b>Pilot:</b> ${esc(b.scope)}</li><li><b>Measure:</b> ${esc(b.measure)}</li></ul></article>`).join('')}<p class="resume-note resume-endnote">The pilots above are proposals. Project measurements describe my own work at the stated checkpoints. The local CRM and locally validated follow-up flows are identified in their project stories.</p><div class="resume-actions"><a class="primary" href="mailto:${esc(data.contact.email)}">Let’s talk</a><a class="secondary" href="${esc(data.contact.linkedin)}" target="_blank" rel="noopener">LinkedIn ↗</a><a class="secondary" href="/${slug}/resume/${esc(data.resume.pdf)}?v=20261027-access" download>Download PDF</a></div>`;
  document.querySelectorAll('[data-project-relevance]').forEach(el=>{el.innerHTML=`<b>Relevant to ${esc(data.name)}:</b> ${esc(data.projectRelevance[el.dataset.projectRelevance])}`;});
 }
 function renderPrompts(){const questions=['Why is CJ a strong fit for this role?','What design decisions went into this?','What would CJ build in the first 30 days?'];$('prompts').innerHTML=questions.map((s,i)=>`<button class="prompt" type="button" data-question="${i}">${s}${icon('arrow')}</button>`).join('')+'<div class="prompt-note">Prepared answers about this portfolio. No live model is connected.</div>';}
 function answer(i){const questions=['Why is CJ a strong fit for this role?','What design decisions went into this?','What would CJ build in the first 30 days?'];let html='';if(i===0)html=`<h4>Commercial judgment and hands-on building</h4><p>${esc(data.pitch)}</p><h4>The evidence behind that fit</h4><ul>${data.mappings.map(r=>`<li><b>${esc(r[0])}:</b> ${esc(r[1])} ${esc(r[2])}</li>`).join('')}</ul><h4>The work, with its scope visible</h4><p>The AI-native résumé shows the source-backed pipeline, local partnership CRM, shipped product work and recoverable commercial workflows, with the implementation checkpoints and measurements retained.</p>`;else if(i===1)html=`<h4>Start with the role’s actual mandate</h4><p>${esc(data.focus)}</p><ul>${data.priorities.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h4>Keep the decision explainable</h4><p>${esc(data.rules.join(' '))}</p><h4>Make the next action useful</h4><p>${esc(data.firstBuilds[0].goal)} ${esc(data.firstBuilds[0].measure)}</p><p>The tabs share one operating cohort so totals, account evidence and handoffs can be inspected together. Operating data is synthetic; the proposal does not imply access to the employer’s systems.</p>`;else html=`<h4>Week one: a usable first workflow</h4><p>${esc(data.weekOne)} Shadow the people using the workflow, agree on a baseline and surface access dependencies.</p>${data.firstBuilds.map((b,j)=>`<h4>${j+1}. ${esc(b.title)}</h4><p>${esc(b.scope)}</p><p><b>Measure:</b> ${esc(b.measure)}</p>`).join('')}<h4>Then expand from evidence</h4><p>${esc(data.days60)} ${esc(data.days90)}</p>`;const t=$('thread');t.querySelector('.welcome')?.remove();t.insertAdjacentHTML('beforeend',`<div class="msg user">${questions[i]}</div><div class="msg bot">${html}</div>`);t.scrollTop=t.scrollHeight;}
 function closeAgent(){document.body.classList.remove('agent-open');$('agent-open')?.setAttribute('aria-expanded','false');$('main').inert=false;document.querySelector('.side').inert=false;$('copilot').removeAttribute('aria-modal');$('copilot').removeAttribute('role');}
 function wire(){
  $('shell').addEventListener('click',e=>{
   const b=e.target.closest('button');if(!b)return;
   if(b.dataset.view){go(b.dataset.view);return;}
   if(b.hasAttribute('data-action-check')){const i=Number(b.dataset.actionCheck);state.done=state.done.includes(i)?state.done.filter(x=>x!==i):[...state.done,i];save();renderPulse();document.querySelector(`[data-action-check="${i}"]`)?.focus({preventScroll:true});return;}
   if(b.dataset.account){openAccount(b.dataset.account);return;}
   if(b.dataset.queueAccount){const id=b.dataset.queueAccount;state.queued=state.queued.includes(id)?state.queued.filter(x=>x!==id):[...state.queued,id];save();b.textContent=state.queued.includes(id)?'Remove from review queue':'Add to review queue';$('queue-status').textContent='Review queue updated in this browser session.';renderSignals();return;}
   if(b.hasAttribute('data-choice')){const g=b.closest('.seg')?.id;if(g==='signal-filter')renderSignals(b.dataset.choice);if(g==='persona-filter')renderSequence(b.dataset.choice);if(g==='experiment-filter')renderExperiments(b.dataset.choice);return;}
   if(b.hasAttribute('data-step')){const card=b.closest('.step-card');card.classList.toggle('open');b.setAttribute('aria-expanded',String(card.classList.contains('open')));return;}
   if(b.dataset.experiment){openExperiment(b.dataset.experiment);return;}
   if(b.dataset.expDecision){state.decisions[b.dataset.expDecision]=b.dataset.decision;save();$('experiment-status').textContent='Saved in this browser: '+b.dataset.decision;renderExperiments();return;}
   if(b.dataset.deal){renderDeals(b.dataset.deal);return;}
   if(b.hasAttribute('data-run-agent')){runAgent(Number(b.dataset.runAgent));return;}
   if(b.hasAttribute('data-question')){answer(Number(b.dataset.question));return;}
   if(b.id==='dialog-close'){$('detail-dialog').close();return;}
   if(b.id==='agent-open'){document.body.classList.add('agent-open');b.setAttribute('aria-expanded','true');$('main').inert=true;document.querySelector('.side').inert=true;$('copilot').setAttribute('role','dialog');$('copilot').setAttribute('aria-modal','true');$('agent-close').focus();return;}
   if(b.id==='agent-close'||b.id==='agent-backdrop'){closeAgent();$('agent-open').focus();return;}
   if(b.id==='logout'||b.hasAttribute('data-logout')){try{sessionStorage.removeItem(key);}catch(_){}$('detail-dialog').close();closeAgent();document.body.classList.add('locked');$('password').focus();}
  });
  $('shell').addEventListener('input',e=>{if(e.target.closest('#workbench-controls'))refreshWorkbench();});
  $('shell').addEventListener('change',e=>{const t=e.target;if(t.id==='funnel-segment')renderFunnel(t.value);if(t.id==='signal-segment')renderSignals(signalFilter,t.value);if(t.id==='lineage-account')renderDataLayer(t.value);if(t.hasAttribute('data-milestone')){const a=data.accounts.find(x=>x.id===t.dataset.id),v=state.milestones[a.id]||a.completeness.map((x,i)=>x?i:-1).filter(i=>i>=0),i=Number(t.dataset.milestone);state.milestones[a.id]=t.checked?[...new Set([...v,i])]:v.filter(x=>x!==i);save();$('milestone-count').textContent=state.milestones[a.id].length+' / 4 readiness checkpoints';document.querySelector('#view-deals .progress-track span').style.width=state.milestones[a.id].length/4*100+'%';$('deal-status').textContent='Readiness saved in this browser session. The funnel cohort is unchanged.';}});
  document.addEventListener('keydown',e=>{if(e.key==='Tab'&&document.body.classList.contains('agent-open')){const items=[...$('copilot').querySelectorAll('button,a[href]')].filter(x=>x.offsetParent!==null),first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.key==='Escape'&&document.body.classList.contains('agent-open')){closeAgent();$('agent-open').focus();}});
 }
 try{if(sessionStorage.getItem(key)==='1')open().catch(()=>{try{sessionStorage.removeItem(key);}catch(_){}$('error').textContent='Unable to load this page. Please try again.';});}catch(_){}
})();
